function SectionCard({ icon, title, subtitle, right, children }: { icon: React.ElementType; title: string; subtitle?: string; right?: React.ReactNode; children: React.ReactNode }) {
  const Icon = icon;
  return (
    <section className="rounded-2xl bg-card border border-border/70 p-4 md:p-5">
      <div className="flex items-center gap-3 mb-4">
        <IconTile icon={Icon as never} size={40} />
        <div className="min-w-0 flex-1">
          <p className="text-[15px] font-bold text-foreground">{title}</p>
          {subtitle && <p className="text-xs text-foreground-secondary">{subtitle}</p>}
        </div>
        {right}
      </div>
      {children}
    </section>
  );
}

function SourceCard({ icon, title, desc, active, onClick, disabled, badge }: { icon: React.ElementType; title: string; desc: string; active: boolean; onClick: () => void; disabled?: boolean; badge?: string }) {
  const Icon = icon;
  return (
    <button type="button" onClick={onClick} disabled={disabled} className={cn('relative text-left rounded-xl border p-3.5 transition-all flex items-start gap-3', active ? 'border-primary bg-primary/10 shadow-[0_0_0_1px_hsl(var(--primary)/.5)]' : 'border-border/70 bg-input/30 hover:border-primary/40', disabled && 'opacity-50 cursor-not-allowed')}>
      <IconTile icon={Icon as never} size={40} color="blue" />
      <div className="min-w-0 flex-1">
        <p className="text-sm font-semibold text-foreground">{title}</p>
        <p className="text-2xs text-foreground-secondary leading-snug mt-0.5">{desc}</p>
        {badge && <span className="inline-block mt-1.5 text-3xs font-semibold px-1.5 py-0.5 rounded bg-muted/60 text-muted-foreground">{badge}</span>}
      </div>
      <span className={cn('w-4 h-4 rounded-full border-2 shrink-0 mt-0.5', active ? 'border-primary bg-primary shadow-[inset_0_0_0_3px_hsl(var(--card))]' : 'border-border')} />
    </button>
  );
}

function StepAudience({ ed }: { ed: WizardState }) {
  // V25 — o passo 1 só oferece segmentos ATIVOS (a página de gestão de
  // segmentos continua mostrando todos). O filtro fica no ponto de uso: a
  // lista vem do hook compartilhado sem alteração.
  const activeSegments = ed.segments.filter((s) => s.status === 'active');
  const segmentSearchTerm = (ed.segmentSearch ?? '').trim().toLowerCase();
  const filteredSegments = useMemo(
    () => activeSegments.filter((s) => !segmentSearchTerm || s.name.toLowerCase().includes(segmentSearchTerm)),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- activeSegments deriva de ed.segments (nova ref a cada render do hook)
    [ed.segments, segmentSearchTerm],
  );
  // X124 — o nome tem faixa (3–200): o aviso aparece logo abaixo do campo e o
  // mesmo limite bloqueia "Continuar" no hook (uma régua só, sem divergir).
  const nameLength = ed.name.trim().length;
  const nameTooShort = nameLength > 0 && nameLength < CAMPAIGN_NAME_MIN_LENGTH;
  const nameTooLong = nameLength > CAMPAIGN_NAME_MAX_LENGTH;
  const selectedObjective = OBJECTIVES.find((o) => o.value === ed.objective);
  return (
    <>
      <SectionCard icon={FileText} title="Informações da campanha">
        <div className="grid grid-cols-1 md:grid-cols-[2fr_1fr_1fr] gap-3">
          <div>
            <Label className="text-xs text-foreground-secondary">Nome da campanha</Label>
            <Input value={ed.name} onChange={(e) => ed.setName(e.target.value)} placeholder="Ex: Lançamento Linha Office" aria-invalid={nameTooShort || nameTooLong} className="mt-1.5 h-10 bg-input/40 border-border/70" />
            {nameTooShort && (
              <p role="alert" className="mt-1.5 text-2xs text-dash-red">O nome precisa de pelo menos {CAMPAIGN_NAME_MIN_LENGTH} caracteres</p>
            )}
            {nameTooLong && (
              <p role="alert" className="mt-1.5 text-2xs text-dash-red">O nome pode ter no máximo {CAMPAIGN_NAME_MAX_LENGTH} caracteres</p>
            )}
          </div>
          <div>
            <Label className="text-xs text-foreground-secondary">Objetivo</Label>
            <Select value={ed.objective} onValueChange={ed.setObjective}>
              <SelectTrigger aria-label="Objetivo" className="mt-1.5 h-10 bg-input/40 border-border/70">
                {/* O gatilho mostra só ícone + rótulo; a descrição do objetivo
                    existe nas opções (e na revisão), não na caixa fechada. */}
                <SelectValue>
                  {selectedObjective ? (
                    <span className="flex items-center gap-2">
                      <selectedObjective.icon className="w-4 h-4 text-muted-foreground" />
                      {selectedObjective.label}
                    </span>
                  ) : ed.objective}
                </SelectValue>
              </SelectTrigger>
              <SelectContent>
                {OBJECTIVES.map(({ value, label, icon: ObjectiveIcon, description }) => (
                  <SelectItem key={value} value={value}>
                    <span className="flex items-start gap-2">
                      <ObjectiveIcon className="mt-0.5 w-4 h-4 text-muted-foreground shrink-0" />
                      <span className="flex min-w-0 flex-col">
                        <span>{label}</span>
                        <span className="text-3xs text-muted-foreground">{description}</span>
                      </span>
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs text-foreground-secondary">Conexão WhatsApp</Label>
            <Select value={ed.connectionId} onValueChange={ed.setConnectionId}>
              <SelectTrigger aria-label="Conexão WhatsApp" className="mt-1.5 h-10 bg-input/40 border-border/70"><SelectValue placeholder="Selecione…" /></SelectTrigger>
              <SelectContent>
                {(ed.connections ?? []).map((c) => <SelectItem key={c.id} value={c.id}>{c.name} ({c.phone_number || 'sem número'})</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        </div>
        <div className="mt-3 grid grid-cols-1 md:grid-cols-[2fr_1fr] gap-3">
          <div><Label className="text-xs text-foreground-secondary">Descrição (opcional)</Label><Input value={ed.description} onChange={(e) => ed.setDescription(e.target.value)} placeholder="Produtos em destaque para escritórios" className="mt-1.5 h-10 bg-input/40 border-border/70" /></div>
          <div>
            <Label className="text-xs text-foreground-secondary">Responsável</Label>
            <Select value={ed.owner ?? ''} onValueChange={ed.setOwner}>
              <SelectTrigger aria-label="Responsável" className="mt-1.5 h-10 bg-input/40 border-border/70"><SelectValue placeholder="Selecione…" /></SelectTrigger>
              <SelectContent>
                {(ed.owners ?? []).map((p) => (
                  <SelectItem key={p.id} value={p.id}>
                    {/* X124 — a lista traz o avatar e o nome do perfil; sem nome
                        cadastrado o e-mail continua sendo a identificação. */}
                    <span className="flex items-center gap-2">
                      <InitialsAvatar name={p.name || p.email || '?'} size={24} />
                      <span className="min-w-0 truncate">{p.name || p.email || 'Sem nome'}</span>
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
        {(ed.connections ?? []).length === 0 && (
          <div className="mt-3">
            <TalkXWhatsAppDisconnectedState onConnect={() => navigateToView('connections')} />
          </div>
        )}
      </SectionCard>

      <SectionCard icon={Users} title="Origem do público" subtitle="Escolha de onde virão os contatos para esta campanha.">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <SourceCard icon={Users} title="Contatos ZAPP" desc="Use seus contatos da plataforma com filtros avançados." active={ed.audienceSource === 'contacts'} onClick={() => ed.setAudienceSource('contacts')} />
          <SourceCard icon={Bookmark} title="Segmento salvo" desc="Utilize um segmento de audiência já salvo." active={ed.audienceSource === 'segment'} onClick={() => ed.setAudienceSource('segment')} disabled={activeSegments.length === 0} badge={activeSegments.length === 0 ? 'Nenhum segmento salvo' : `${activeSegments.length} segmentos`} />
          <SourceCard icon={Database} title="CRM 360°" desc="Selecione contatos do seu CRM com base em negócios e estágios." active={ed.audienceSource === 'crm360'} onClick={() => ed.setAudienceSource('crm360')} disabled badge="Vinculação CRM 360° não configurada" />
        </div>
        {ed.audienceSource === 'segment' && (
          <>
            <div className="mt-4 mb-2">
              <label htmlFor="talkx-seg-search" className="sr-only">Buscar segmentos por nome</label>
              <input id="talkx-seg-search" type="search" placeholder="Buscar segmento por nome…" aria-label="Buscar segmentos por nome" value={ed.segmentSearch ?? ''} onChange={(e) => ed.setSegmentSearch(e.target.value)} className="w-full rounded-lg border border-input bg-input/30 px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary/20" />
            </div>
            <div className="mt-2 flex flex-wrap gap-2">
              {filteredSegments.map((s) => {
                const active = ed.segmentIds.includes(s.id);
                const perSegment = ed.segmentEstimates?.[s.id] ?? s.estimated_count ?? null;
                return (
                  <button key={s.id} type="button" onClick={() => ed.toggleSegmentId(s.id)} aria-pressed={active} className={cn('inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-medium transition-all', active ? 'border-primary bg-primary/10 text-primary' : 'border-border/70 bg-input/30 text-foreground hover:border-primary/40')}>
                    {s.name}
                    {perSegment != null && <span className="font-normal opacity-80">({fmtInt(perSegment)})</span>}
                    {active && <X className="h-3 w-3 text-primary" aria-hidden="true" />}
                  </button>
                );
              })}
            </div>
            {filteredSegments.length === 0 && (
              <p className="mt-3 text-xs text-muted-foreground">Nenhum segmento encontrado.</p>
            )}
            {ed.selectedSegments.length > 0 && (
              <div className="mt-3">
                <p id="talkx-seg-chosen" className="mb-1.5 text-xs font-medium text-foreground-secondary">Segmentos escolhidos:</p>
                <div role="group" aria-labelledby="talkx-seg-chosen" className="flex flex-wrap gap-1.5">
                  {ed.selectedSegments.map((s) => (
                    <span key={s.id} className="inline-flex items-center gap-1 rounded-full border border-primary/40 bg-primary/10 px-2.5 py-1 text-xs font-medium text-primary">
                      {s.name}
                      <button type="button" onClick={() => ed.toggleSegmentId(s.id)} className="ml-1 inline-flex h-4 w-4 items-center justify-center rounded-full hover:bg-primary/20" aria-label={`Remover ${s.name} dos escolhidos`} title="Remover dos escolhidos">
                        <X className="h-3 w-3" aria-hidden="true" />
                        <span className="sr-only">Remover dos escolhidos</span>
                      </button>
                    </span>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </SectionCard>

      {ed.audienceSource === 'contacts' && (
        <SectionCard icon={Filter} title="Filtros de audiência" subtitle="Refine seu público com regras (mesmas dos segmentos) e selecione os contatos."
          right={<span className="text-3xs text-muted-foreground">{typeof ed.audienceCount === 'number' ? `${fmtInt(ed.audienceCount)} contatos atendem aos filtros` : 'Contando público…'}</span>}>
          <TalkXAudienceFilters
            rules={ed.audienceRules}
            onChange={ed.setAudienceRules}
            options={{
              companies: ed.companies,
              sellers: (ed.owners ?? []).map((p) => ({ id: p.id, name: p.name || p.email || 'Sem nome' })),
            }}
            onClear={ed.clearFilters}
          />
          <div className="mt-3">
          <TalkXContactSelector
            contacts={ed.contacts || []}
            filteredContacts={ed.filteredContacts}
            selectedContacts={ed.selectedContacts}
            contactSearch={ed.contactSearch}
            setContactSearch={ed.setContactSearch}
            companyFilter={ed.companyFilter}
            setCompanyFilter={ed.setCompanyFilter}
            companies={ed.companies}
            toggleContact={ed.toggleContact}
            selectAll={ed.selectAll}
            clearFilters={ed.clearFilters}
          />
          </div>
        </SectionCard>
      )}
    </>
  );
}

